  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  @@index([token], map: "discussion_board_super_administrator_email_verificatio_5482dfc5")
  // spellchecker: ignore-next-line
  @@index([email], map: "discussion_board_super_administrator_email_verificatio_14e13d67")
